Given an arr[] of elements of size n, return the largest element given in the array.Examples:Input: arr[] = [10, 20, 4]Output: 20Explanation: Among 10, 20 and 4, 20 is the largest. Input: arr[] = [20, 10, 20, 4, 100]Output: 100Try It YourselfTable of ContentIterative Approach - O(n) Time and O(1) SpaceRecursive Approach - O(n) Time and O(n) SpaceUsing Library Methods - O(n) Time and O(1) SpaceIterative Approach - O(n) Time and O(1) SpaceTraverse the entire array and keep track of the largest element encountered. Update the maximum value whenever a larger element is found, and after scanning all elements, the stored value represents the largest element in the array.
            C++

    #include <iostream>
#include <vector>
using namespace std;

int largest(vector<int>& arr) {
    int max = arr[0];

    //Traverse  from second and compare
    // every element with current max
    for (int i = 1; i < arr.size(); i++)
        if (arr[i] > max)
            max = arr[i];

    return max;
}

int main() {
    vector<int> arr = {20, 10, 20, 4, 100};
    cout << largest(arr);
    return 0;
}


