            C

    #include <stdio.h>
#include <stdlib.h>

int compare(const void* a, const void* b) {
    return (*(int*)a - *(int*)b);
}

int largest(int arr[], int n) {
    qsort(arr, n, sizeof(int), compare);
    return arr[n - 1];
}

int main() {
    int arr[] = {20, 10, 20, 4, 100};
    int n = sizeof(arr) / sizeof(arr[0]);
    printf("%d\n", largest(arr, n));
    return 0;
}


